import React, { useState } from 'react';
import { 
  Box, 
  Typography, 
  Paper, 
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  IconButton,
  Tooltip,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Snackbar,
  Alert,
  CircularProgress
} from '@mui/material';
import { 
  Delete as DeleteIcon,
  Visibility as VisibilityIcon
} from '@mui/icons-material';
import { useQuery, useMutation } from '@apollo/client';
import { GET_ALL_MESSAGES, DELETE_MESSAGE, UPDATE_MESSAGE_STATUS } from '../../../graphql/admin';
import { format } from 'date-fns';

const MESSAGES_PER_PAGE = 10;

const Messages = () => {
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(MESSAGES_PER_PAGE);
  const [selectedMessage, setSelectedMessage] = useState(null);
  const [viewDialogOpen, setViewDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [messageToDelete, setMessageToDelete] = useState(null);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  // State for pagination and filtering
  const [filters, setFilters] = useState({
    type: 'all', // 'inbox', 'sent', or 'all'
    messageType: '',
    page: 1,
    limit: MESSAGES_PER_PAGE
  });

  // Fetch messages with pagination and filters
  const { loading, error, data, refetch } = useQuery(GET_ALL_MESSAGES, {
    variables: {
      type: filters.type,
      messageType: filters.messageType || undefined,
      page: filters.page,
      limit: filters.limit
    },
    fetchPolicy: 'cache-and-network',
    onCompleted: (data) => {
      console.log('Messages query completed:', data);
      if (data?.messages?.messages?.length === 0) {
        console.log('No messages found with current filters');
      }
    },
    onError: (error) => {
      console.error('Error fetching messages:', error);
      setSnackbar({
        open: true,
        message: `Error loading messages: ${error.message}`,
        severity: 'error',
      });
    },
  });

  // Handle page change
  const handleChangePage = (event, newPage) => {
    setFilters(prev => ({
      ...prev,
      page: newPage + 1 // Convert from 0-based to 1-based
    }));
    setPage(newPage);
  };

  // Handle rows per page change
  const handleChangeRowsPerPage = (event) => {
    const newLimit = parseInt(event.target.value, 10);
    setRowsPerPage(newLimit);
    setPage(0);
    setFilters(prev => ({
      ...prev,
      limit: newLimit,
      page: 1
    }));
  };

  const [deleteMessage] = useMutation(DELETE_MESSAGE, {
    onCompleted: () => {
      setSnackbar({
        open: true,
        message: 'Message deleted successfully',
        severity: 'success'
      });
      refetch();
      setDeleteDialogOpen(false);
    },
    onError: (error) => {
      setSnackbar({
        open: true,
        message: `Error deleting message: ${error.message}`,
        severity: 'error'
      });
    }
  });

  // Handle delete confirmation
  const handleConfirmDelete = () => {
    if (messageToDelete) {
      deleteMessage({ 
        variables: { 
          messageId: messageToDelete.id 
        } 
      });
    }
  };

  const [updateMessageStatus] = useMutation(UPDATE_MESSAGE_STATUS, {
    onCompleted: () => {
      refetch();
    },
    onError: (error) => {
      console.error('Error updating message status:', error);
    }
  });

  const handleViewMessage = (message) => {
    setSelectedMessage(message);
    setViewDialogOpen(true);

    // Mark as read if unread
    if (message.status === 'unread') {
      updateMessageStatus({
        variables: {
          id: message.id,
          status: 'read'
        }
      });
    }
  };

  const handleDeleteClick = (message) => {
    setMessageToDelete(message);
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = () => {
    if (messageToDelete) {
      deleteMessage({
        variables: {
          id: messageToDelete.id
        }
      });
    }
  };

  const handleCloseSnackbar = () => {
    setSnackbar(prev => ({ ...prev, open: false }));
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    return format(new Date(dateString), 'PPpp');
  };

  const getStatusColor = (status) => {
    if (!status) return 'default';

    const statusLower = status.toLowerCase();
    switch (statusLower) {
      case 'read':
        return 'success';
      case 'unread':
        return 'primary';
    }
  };

  const paginatedMessages = data?.messages?.messages || [];
  const totalCount = data?.messages?.totalCount || 0;

  if (loading && !data) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="200px">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={3}>
        <Alert severity="error">
          Error loading messages: {error.message}
        </Alert>
      </Box>
    );
  }

  return (
    <Box p={3}>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h5" component="h1">
          Messages Inbox
        </Typography>
      </Box>

      <Paper>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Subject</TableCell>
                <TableCell>Type</TableCell>
                <TableCell>Recipient</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Sent At</TableCell>
                <TableCell>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {paginatedMessages.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} align="center" style={{ padding: '20px' }}>
                    <Typography color="textSecondary">
                      No messages found
                    </Typography>
                  </TableCell>
                </TableRow>
              ) : (
                paginatedMessages.map((message) => (
                  <TableRow 
                    key={message.id}
                    hover
                    style={{
                      cursor: 'pointer',
                      backgroundColor: message.status === 'unread' ? '#f5f9ff' : 'inherit'
                    }}
                  >
                    <TableCell onClick={() => handleViewMessage(message)}>
                      {message.subject || 'No Subject'}
                    </TableCell>
                    <TableCell onClick={() => handleViewMessage(message)}>
                      <Chip 
                        label={message.messageType || 'email'}
                        size="small"
                        color="primary"
                        variant="outlined"
                      />
                    </TableCell>
                    <TableCell onClick={() => handleViewMessage(message)}>
                      {message.recipientType === 'all' 
                        ? 'All Users' 
                        : message.recipientType === 'client' 
                          ? 'All Clients' 
                          : message.recipientType === 'staff' 
                            ? 'All Staff' 
                            : `User ID: ${message.recipientId || 'N/A'}`}
                    </TableCell>
                    <TableCell onClick={() => handleViewMessage(message)}>
                      <Chip 
                        label={message.status || 'unknown'}
                        size="small"
                        color={getStatusColor(message.status)}
                        variant="outlined"
                      />
                    </TableCell>
                    <TableCell onClick={() => handleViewMessage(message)}>
                      {message.sentAt ? formatDate(message.sentAt) : 'Not sent'}
                    </TableCell>
                    <TableCell align="right">
                      <Tooltip title="View">
                        <IconButton 
                          size="small" 
                          onClick={() => handleViewMessage(message)}
                          color="primary"
                        >
                          <VisibilityIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                      <Tooltip title="Delete">
                        <IconButton 
                          size="small" 
                          onClick={(e) => {
                            e.stopPropagation();
                            handleDeleteClick(message);
                          }}
                          color="error"
                        >
                          <DeleteIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>

        <TablePagination
          rowsPerPageOptions={[5, 10, 25]}
          component="div"
          count={totalCount}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
        />
      </Paper>

      {/* View Message Dialog */}
      <Dialog 
        open={viewDialogOpen} 
        onClose={() => setViewDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          {selectedMessage?.subject || 'Message Details'}
        </DialogTitle>
        <DialogContent dividers>
          <Box mb={2}>
            <Typography variant="subtitle2" color="textSecondary">From:</Typography>
            <Typography>
              {selectedMessage?.name}
              {selectedMessage?.email && ` <${selectedMessage.email}>`}
            </Typography>
          </Box>

          <Box mb={2}>
            <Typography variant="subtitle2" color="textSecondary">Phone:</Typography>
            <Typography>{selectedMessage?.phone || 'N/A'}</Typography>
          </Box>

          <Box mb={2}>
            <Typography variant="subtitle2" color="textSecondary">Date:</Typography>
            <Typography>{formatDate(selectedMessage?.createdAt)}</Typography>
          </Box>

          <Box mb={2}>
            <Typography variant="subtitle2" color="textSecondary">Status:</Typography>
            <Chip 
              label={selectedMessage?.status || 'unread'}
              color={getStatusColor(selectedMessage?.status)}
              size="small"
            />
          </Box>

          <Box mb={2}>
            <Typography variant="subtitle2" color="textSecondary">Subject:</Typography>
            <Typography>{selectedMessage?.subject || 'No subject'}</Typography>
          </Box>

          <Box mt={3}>
            <Typography variant="subtitle2" color="textSecondary" gutterBottom>Message:</Typography>
            <Paper variant="outlined" style={{ padding: '16px', whiteSpace: 'pre-wrap' }}>
              {selectedMessage?.message || 'No content'}
            </Paper>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setViewDialogOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
      >
        <DialogTitle>Delete Message</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to delete this message? This action cannot be undone.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteDialogOpen(false)}>Cancel</Button>
          <Button 
            onClick={handleDeleteConfirm} 
            color="error"
            variant="contained"
          >
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert 
          onClose={handleCloseSnackbar} 
          severity={snackbar.severity}
          variant="filled"
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default Messages;
